/* UCIRP Coimbatore – browser app. Talks to the Node.js REST API in server.js. */
const $=s=>document.querySelector(s);
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const H=36e5,now=()=>Date.now();
let DEPTS={},AGENCIES={},DEPT_AG={},WARDS={},CATS={},USERS={},DEMO=[],LIVE={},me=null;
let S={weights:{},karmaPts:10,karma:0,audit:[],notes:[],issues:[],wos:[]};
let view="gate",cur=null,charts=[],portal="citizen",go=null,lang=localStorage.getItem("ucirp-lang")==="ta"?"ta":"en",FL={q:"",s:""},PICK={lat:11.0050,lng:76.9700};
const wardOf=(la,lo)=>Object.keys(WARDS).map(k=>({k,d:(WARDS[k].la-la)**2+(WARDS[k].lo-lo)**2})).sort((a,b)=>a.d-b.d)[0].k;
const uname=k=>esc(USERS[k]?USERS[k].n:k);
const CA=CityAlgorithms;
const ag=x=>esc((AGENCIES[x.agency]||{s:"GCC"}).s);

/* ---------------- server API ---------------- */
async function http(method,url,body){let r;try{r=await fetch(url,{method,credentials:"same-origin",headers:body?{"Content-Type":"application/json"}:{},body:body?JSON.stringify(body):undefined})}catch(e){const er=new Error("Cannot reach the server. Check that it is still running.");er.offline=true;wentOffline();throw er}
 let j=null;try{j=await r.json()}catch(e){}if(!r.ok){const e=new Error(j&&j.error||"Request failed ("+r.status+")");e.status=r.status;throw e}return j}
const P=(u,b)=>http("POST",u,b||{});
function apply(j,cached){DEPTS=j.depts;AGENCIES=j.agencies;DEPT_AG=j.deptAgencies;WARDS=j.wards;CATS=j.cats;USERS=j.users;DEMO=j.demo;LIVE=j.live||{};S=j.S;me=j.me;
 // mirror the server data in this browser so the app still opens if the server is down (a fallback copy, not a sync mechanism)
 if(!cached){cacheT=now();try{localStorage.setItem("ucirp-cache",JSON.stringify({t:cacheT,j:{...j,live:{},S:{...j.S,audit:(j.S.audit||[]).slice(0,300)}}}))}catch(e){}}addQueued()}
async function refresh(){const was=me;apply(await http("GET","/api/state"));if(OFFLINE){clearInterval(offT);offT=null;OFFLINE=false;offBar();setTimeout(flushOutbox,0)}if(was&&!me){view="gate";toast("Your session ended. Please sign in again.")}}
const api={
 verify:id=>P(`/api/issues/${id}/verify`),reject:(id,why)=>P(`/api/issues/${id}/reject`,{reason:why}),info:(id,why)=>P(`/api/issues/${id}/info`,{reason:why}),
 reply:(id,text)=>P(`/api/issues/${id}/reply`,{text}),route:(id,dept,agency)=>P(`/api/issues/${id}/route`,{dept,agency}),
 createWO:(id,b)=>P(`/api/issues/${id}/work-orders`,b),act:(wid,action,b)=>P(`/api/work-orders/${wid}/${action}`,b),
 override:(wid,why)=>P(`/api/work-orders/${wid}/override`,{reason:why}),review:(wid,ok,why)=>P(`/api/work-orders/${wid}/review`,{approve:ok,reason:why||""}),
 reassign:(wid,crew)=>P(`/api/work-orders/${wid}/reassign`,{crew}),dup:(id,ok,why)=>P(`/api/issues/${id}/duplicate`,{accept:ok,reason:why||""}),merge:(id,into,why)=>P(`/api/issues/${id}/merge`,{into,reason:why}),prio:(id,b)=>P(`/api/issues/${id}/priority`,b),confirm:id=>P(`/api/issues/${id}/confirm`),dispute:(id,why)=>P(`/api/issues/${id}/dispute`,{reason:why}),support:id=>P(`/api/issues/${id}/support`)};
// run a server action, reload the data, then redraw
window.run=async(f,after)=>{try{await f();await refresh();if(after)after()}catch(e){toast(e.offline?"The server is unreachable, so this action cannot be done right now. You are looking at the copy saved in this browser.":(e.status===403?"Not allowed: ":"")+(e.message||e));if(!e.offline)try{await refresh()}catch(_){}}render()};

/* ---------------- offline fallback (browser localStorage) ---------------- */
let OFFLINE=false,offT=null,cacheT=0;
const outbox=()=>{try{return JSON.parse(localStorage.getItem("ucirp-outbox")||"[]")}catch(e){return[]}};
const setOutbox=l=>{try{localStorage.setItem("ucirp-outbox",JSON.stringify(l));return true}catch(e){return false}};
const loadCache=()=>{try{const c=JSON.parse(localStorage.getItem("ucirp-cache"));return c&&c.j&&c.j.S?c:null}catch(e){return null}};
// a complaint written while the server was down, shown in the list until it can be sent
function pseudo(o){const b=o.body,dept=CATS[b.cat],g=CA.guessSev(b.desc);return{id:o.id,local:true,cat:b.cat,dept,agency:CA.routeAgency(dept,b.cat,b.street,b.desc),ward:b.ward,street:b.street,landmark:b.landmark,desc:b.desc,sev:b.sos?1:g.sev,safety:g.safety,sens:Math.max(g.sens,CA.sensitiveNear(b).s),recur:0,status:"Queued (offline)",by:[o.u],support:1,verified:false,wos:[],lat:b.lat,lng:b.lng,acc:b.acc,t:o.t,sos:b.sos,photos:b.photos,before:b.photos[0],reports:[],ph:b.hashes||[],conf:70,defect:CA.DEFECT[b.cat]}}
function addQueued(){S.issues=(S.issues||[]).filter(i=>!i.local).concat(me?outbox().filter(o=>o.u===me&&CATS[o.body.cat]).map(pseudo):[])}
function offBar(){const el=$("#off");if(!el)return;const n=outbox().length;el.hidden=!OFFLINE&&!n;el.textContent=OFFLINE?"Server unreachable. You are seeing the copy saved in this browser"+(cacheT?" at "+fmt(cacheT):"")+". New complaints are kept here and sent when the server is back."+(n?" Waiting to send: "+n+".":""):n+" saved complaint(s) are being sent to the server…"}
function wentOffline(){if(OFFLINE)return;OFFLINE=true;offBar();clearInterval(offT);offT=setInterval(probe,5000)}
async function probe(){let j;try{const r=await fetch("/api/state",{credentials:"same-origin",cache:"no-store"});if(!r.ok)return;j=await r.json()}catch(e){return}
 clearInterval(offT);offT=null;OFFLINE=false;apply(j);await flushOutbox();connectES();offBar();toast("Back online. Data refreshed from the server.");if(view==="gate"&&me)view="home";if(!busy())render();else $("#upd").hidden=false}
async function flushOutbox(){if(!me)return;let sent=0;for(const o of outbox()){if(o.u!==me)continue;try{const r=await P("/api/issues",o.body);sent++;setOutbox(outbox().filter(x=>x.id!==o.id));toast(r.linked?"Saved report linked to "+r.id:"Saved report sent. Reference ID "+r.id);if(cur===o.id)cur=r.id}catch(e){if(e.offline)return;setOutbox(outbox().filter(x=>x.id!==o.id));toast("A saved report was not accepted: "+e.message)}}
 if(sent)try{apply(await http("GET","/api/state"))}catch(e){}addQueued();offBar()}

/* ---------------- live updates (server-sent events) ---------------- */
let ES=null,rfT=null;
function connectES(){if(ES)ES.close();ES=new EventSource("/api/events");
 ES.addEventListener("change",()=>{clearTimeout(rfT);rfT=setTimeout(onChange,250)});
 ES.addEventListener("loc",e=>{const d=JSON.parse(e.data);if(d.gone)delete LIVE[d.u];else LIVE[d.u]=d;liveDraw()});
 ES.onerror=()=>{if(!OFFLINE)http("GET","/api/state").catch(()=>{})}}
const unread=()=>S.notes.filter(n=>!n.read).length;
function busy(){if(["new","sos","login"].includes(view))return true;const a=document.activeElement;if(a&&a.closest&&a.closest("#main")&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName))return true;
 return[...document.querySelectorAll("#main textarea,#main input")].some(e=>e.type==="file"?e.files.length:e.type==="checkbox"?e.checked!==e.defaultChecked:e.value!==e.defaultValue)}
async function onChange(){const before=JSON.stringify(S),u0=unread();try{await refresh()}catch(e){return}
 if(me&&unread()>u0){const n=S.notes.find(x=>!x.read);if(n)toast("🔔 "+n.m)}
 if(JSON.stringify(S)===before)return;if(busy()){if(me)renderNav();$("#upd").hidden=view==="login"}else render()}

/* ---------------- helpers ---------------- */
// 64-bit average hash of a photo: the "image" part of the duplicate score
const ahash=src=>new Promise(r=>{const im=new Image();im.onload=()=>{try{const c=document.createElement("canvas");c.width=c.height=8;const x=c.getContext("2d");x.drawImage(im,0,0,8,8);const d=x.getImageData(0,0,8,8).data,g=[];for(let k=0;k<64;k++)g.push(d[k*4]*.299+d[k*4+1]*.587+d[k*4+2]*.114);const avg=g.reduce((a,b)=>a+b,0)/64;let h="";for(let k=0;k<64;k+=4)h+=((g[k]>avg?8:0)|(g[k+1]>avg?4:0)|(g[k+2]>avg?2:0)|(g[k+3]>avg?1:0)).toString(16);r(h)}catch(e){r(null)}};im.onerror=()=>r(null);im.src=src});
const thumb=(f,max=1280,q=.8)=>new Promise(r=>{if(!f)return r(null);const rd=new FileReader();rd.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,max/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));c.getContext("2d").drawImage(im,0,0,c.width,c.height);r(c.toDataURL("image/jpeg",q))};im.onerror=()=>r(null);im.src=rd.result};rd.onerror=()=>r(null);rd.readAsDataURL(f)});
const ROLE={citizen:"Citizen",officer:"Ward verification officer",supervisor:"Department supervisor",crew:"Field engineer",admin:"City administrator"};
const I=id=>S.issues.find(i=>i.id===id),W=id=>S.wos.find(w=>w.id===id);
const fmt=t=>new Date(t).toLocaleString("en-IN",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"});
const km=d=>d>=1000?(d/1000).toFixed(1)+" km":Math.round(d)+" m";
// priority score, band and SLA state come from CityAlgorithms: the same rules the server uses
function score(i){const r=CA.score(i,S.weights);return{p:r.parts,tot:r.total,w:r.weights,calc:r.computed,po:r.override}}
const pr=i=>score(i).tot;
const BC={Critical:"bad",High:"warn",Medium:"",Low:"ok"},SC={"On Track":"ok","At Risk":"warn",Breached:"bad"};
function band(i){const b=CA.band(pr(i));return[b,BC[b]]}
const openWO=w=>w&&!["Verified","Completed","Cancelled"].includes(w.status);
function sla(w){const x=CA.slaState(w,now()),h=Math.abs(x.left)/H,hh=Math.round(h),d=hh>=24?Math.floor(hh/24)+"d "+(hh%24)+"h":h>=1?hh+"h":Math.max(1,Math.round(h*60))+" min";return`<span class="tag ${SC[x.state]}">${x.state} · ${x.left<0?d+" overdue":d+" left"}</span>`}
function slaTag(i){const o=["On Track","At Risk","Breached"],l=i.wos.map(W).filter(openWO).map(w=>CA.slaState(w,now()).state).sort((a,b)=>o.indexOf(b)-o.indexOf(a));return l.length?` <span class="tag ${SC[l[0]]}">${l[0]}</span>`:""}
const photosOf=i=>i.photos&&i.photos.length?i.photos:i.before?[i.before]:[];
const st=s=>`<span class="tag ${/Closed|Verified|Completed|Resolved/.test(s)?"ok":/Rework|Rejected|Blocked|Escalated|Reopened/.test(s)?"bad":/Needs|Under|Submitted|Queued/.test(s)?"warn":""}">${s}</span>`;
function toast(m){const t=$("#toast");t.textContent=lang==="ta"&&TA[m]||m;t.style.display="block";clearTimeout(t.h);t.h=setTimeout(()=>t.style.display="none",2600+String(m).length*35)}
const ACTIVE=["Accepted","In Progress"];

/* ---------------- GPS: one shared high-accuracy watcher ---------------- */
const GEO={id:null,pos:null,denied:false};let SHOWME=false,PICKING=false,SHARE=false,pickBest=null,pickT=null,lastPost=0,centerOn=null;
function geoSync(){const need=SHOWME||PICKING||SHARE;
 if(need&&GEO.id==null){if(!navigator.geolocation){toast("GPS is not available on this device");return}
  if(GEO.denied)return;GEO.id=navigator.geolocation.watchPosition(onPos,onGeoErr,{enableHighAccuracy:true,maximumAge:0,timeout:30000})}
 else if(!need&&GEO.id!=null){navigator.geolocation.clearWatch(GEO.id);GEO.id=null}}
function onPos(p){const c=p.coords;GEO.pos={lat:c.latitude,lng:c.longitude,acc:c.accuracy,spd:c.speed,hdg:c.heading,t:now()};
 if(PICKING){if(pickBest==null||c.accuracy<pickBest){pickBest=c.accuracy;setPick({lat:c.latitude,lng:c.longitude},c.accuracy,true)}if(c.accuracy<=15){endPick();toast("Exact location locked (±"+Math.round(c.accuracy)+" m)")}}
 if(SHOWME)meDraw();
 if(SHARE&&me&&now()-lastPost>4000){lastPost=now();const b={lat:c.latitude,lng:c.longitude,acc:c.accuracy};if(c.speed!=null&&!isNaN(c.speed))b.spd=c.speed;if(c.heading!=null&&!isNaN(c.heading))b.hdg=c.heading;http("POST","/api/location",b).catch(()=>{});LIVE[me]={u:me,...b,t:now()};liveDraw()}}
function onGeoErr(e){const insecure=!window.isSecureContext;
 if(e.code===1){GEO.denied=true;if(GEO.id!=null){navigator.geolocation.clearWatch(GEO.id);GEO.id=null}const wasPick=PICKING;endPick();SHOWME=false;SHARE=false;locBtns();shareBtn();
  toast(insecure?"GPS needs the secure address. Open the https:// link shown in the server window.":wasPick?"Location permission denied. Allow location for this page, or drag the pin on the map.":"Location permission denied. Allow location for this page in the browser settings.")}
 else if(PICKING&&pickBest==null)toast(e.code===3?"Still searching for GPS. Move near a window or open sky.":"Location unavailable. Drag the pin on the map instead.")}
function endPick(){PICKING=false;clearTimeout(pickT);pickBest=null;geoSync()}
window.gps=()=>{if(!navigator.geolocation)return toast("GPS is not available on this device");endPick();GEO.denied=false;PICKING=true;pickBest=null;toast("Getting your exact location…");geoSync();
 pickT=setTimeout(()=>{const b=pickBest;endPick();if(b!=null)toast(b<=50?"Location locked (±"+Math.round(b)+" m). Drag the pin to fine tune.":"Best fix is ±"+Math.round(b)+" m. A phone outdoors is more exact. Drag the pin to adjust.");else toast("No GPS fix yet. Drag the pin on the map instead.")},25000)};
// one position fix for stamping evidence (returns null if GPS is unavailable)
const oneFix=ms=>new Promise(r=>{if(GEO.pos&&now()-GEO.pos.t<60000)return r(GEO.pos);if(!navigator.geolocation||GEO.denied)return r(null);const t=setTimeout(()=>r(null),ms+500);navigator.geolocation.getCurrentPosition(p=>{clearTimeout(t);r({lat:p.coords.latitude,lng:p.coords.longitude,acc:p.coords.accuracy})},()=>{clearTimeout(t);r(null)},{enableHighAccuracy:true,maximumAge:30000,timeout:ms})});

/* crew live-location sharing */
const shareOff=()=>localStorage.getItem("ucirp-share")==="off";
const shareWanted=()=>!!me&&USERS[me]&&USERS[me].role==="crew"&&!shareOff()&&S.wos.some(w=>w.crew===me&&ACTIVE.includes(w.status));
function shareBtn(){const b=$("#share"),crew=!!me&&USERS[me]&&USERS[me].role==="crew";b.hidden=!crew;if(!crew)return;b.textContent=SHARE?"📡 Live location ON":shareOff()?"📡 Live location OFF":GEO.denied?"📡 Location blocked":"📡 Live location idle";b.setAttribute("aria-pressed",SHARE?"true":"false");b.title="Your position is shared with the ward office and the citizen only while a work order is accepted or in progress."}
function shareSync(){const want=shareWanted()&&!GEO.denied;if(want&&!SHARE){SHARE=true;lastPost=0;geoSync()}else if(!want&&SHARE){SHARE=false;geoSync();if(me)http("POST","/api/location/stop",{}).catch(()=>{})}shareBtn()}
$("#share").onclick=()=>{if(shareOff()||GEO.denied){localStorage.setItem("ucirp-share","on");GEO.denied=false;shareSync();toast(SHARE?"Live location sharing is on.":"Sharing starts automatically when you accept a work order.")}else{localStorage.setItem("ucirp-share","off");shareSync();toast("Live location sharing is off.")}};

/* ---------------- maps (Leaflet street map, with SVG fallback from mapbase.js) ---------------- */
let TILE_ALT=false;const LMO={},LMAP={},USE_L=()=>!!window.L&&navigator.onLine!==false;
function killMaps(){Object.keys(LMAP).forEach(k=>{try{LMAP[k].map.off();LMAP[k].map.remove()}catch(e){}delete LMAP[k]})}
function mapSVG(id,o={}){if(USE_L()){LMO[id]=o;return`<div class="mapw"><div id="${id}" class="lmap" style="height:${o.h||340}px" role="application" aria-label="Map"></div></div>`}return mapSVG0(id,o)}
function locBtns(){document.querySelectorAll(".lloc").forEach(b=>b.classList.toggle("on",SHOWME))}
function meDraw(){const p=GEO.pos;Object.keys(LMAP).forEach(id=>{const r=LMAP[id];if(!SHOWME||!p){if(r.me){r.map.removeLayer(r.me);r.map.removeLayer(r.meAc);r.me=r.meAc=null}return}
  if(!r.me){r.meAc=L.circle([p.lat,p.lng],{radius:p.acc||0,color:"#1a73e8",weight:1,fillOpacity:.1,interactive:false}).addTo(r.map);r.me=L.marker([p.lat,p.lng],{interactive:false,zIndexOffset:900,icon:L.divIcon({className:"",html:'<span class="lme"></span>',iconSize:[22,22],iconAnchor:[11,11]})}).addTo(r.map)}
  r.me.setLatLng([p.lat,p.lng]);r.meAc.setLatLng([p.lat,p.lng]);r.meAc.setRadius(p.acc||0);
  if(centerOn===id){centerOn=null;r.map.setView([p.lat,p.lng],Math.max(r.map.getZoom(),16),{animate:false});toast("You are here (±"+Math.round(p.acc)+" m). The dot follows you.")}})}
function lInit(id,o){const el=$("#"+id);if(!el)return;if(LMAP[id]){try{LMAP[id].map.remove()}catch(e){}}
 const c=o.focus||o.pick||{lat:11.0150,lng:76.9750},m=L.map(el,{maxZoom:19,zoomSnap:.5,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([c.lat,c.lng],o.focus?17:o.pick?15:12);
 // street map: Esri tiles, switching by itself to OpenStreetMap if Esri tiles fail; satellite: Esri imagery
 const esri=n=>"https://server.arcgisonline.com/ArcGIS/rest/services/"+n+"/MapServer/tile/{z}/{y}/{x}",osm=()=>L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'});
 let tl=(TILE_ALT?osm():L.tileLayer(esri("World_Street_Map"),{maxZoom:19,maxNativeZoom:17,attribution:"Tiles © Esri"})).addTo(m); // Esri has no street tiles deeper than level 17 here, so closer zooms enlarge level 17
 const sat=L.tileLayer(esri("World_Imagery"),{maxZoom:19,maxNativeZoom:18,attribution:"Tiles © Esri"});
 let bad=0,satOn=false;const onBad=()=>{if(++bad!==4)return;if(!TILE_ALT){TILE_ALT=true;bad=0;const was=tl;tl=osm().on("tileerror",onBad);if(!satOn){m.removeLayer(was);tl.addTo(m)}}else toast("Street map tiles could not load. Check your internet. Coordinates stay exact.")};[tl,sat].forEach(x=>x.on("tileerror",onBad));
 const Ctl=L.Control.extend({onAdd(){const b=L.DomUtil.create("button","lsw");b.type="button";b.textContent="Satellite";L.DomEvent.disableClickPropagation(b);b.onclick=e=>{L.DomEvent.stop(e);satOn=!satOn;if(satOn){m.removeLayer(tl);sat.addTo(m);b.textContent="Street"}else{m.removeLayer(sat);tl.addTo(m);b.textContent="Satellite"}};return b}});new Ctl({position:"topright"}).addTo(m);
 const Loc=L.Control.extend({onAdd(){const b=L.DomUtil.create("button","lloc"+(SHOWME?" on":""));b.type="button";b.textContent="◎";b.title="Show my live location";b.setAttribute("aria-label","Show my live location");L.DomEvent.disableClickPropagation(b);
   b.onclick=e=>{L.DomEvent.stop(e);if(!navigator.geolocation)return toast("GPS is not available on this device");SHOWME=!SHOWME;locBtns();if(SHOWME){GEO.denied=false;centerOn=id;geoSync();if(GEO.pos&&now()-GEO.pos.t<30000)meDraw();else toast("Finding your location…")}else{meDraw();geoSync()}};return b}});new Loc({position:"topleft"}).addTo(m);
 L.control.scale({imperial:false}).addTo(m);
 const col={bad:"#a61b1b",warn:"#e39b12",ok:"#0d7a4a",md:"#1769e0"},pts=[];
 (o.pins||[]).forEach(i=>{pts.push([i.lat,i.lng]);if(o.heat)L.circle([i.lat,i.lng],{radius:60+pr(i)*3,color:"#a61b1b",weight:0,fillOpacity:.14,interactive:false}).addTo(m);
  L.marker([i.lat,i.lng],{icon:L.divIcon({className:"",html:`<span class="lpin" style="background:${col[band(i)[1]||"md"]}"></span>`,iconSize:[18,18],iconAnchor:[9,9]}),title:i.id+" · "+i.cat,alt:i.id}).addTo(m).on("click",()=>openI(i.id))});
 if(!o.focus&&!o.pick&&pts.length)m.fitBounds(pts,{padding:[30,30],maxZoom:16,animate:false});
 const rec={map:m,lv:L.layerGroup().addTo(m)};LMAP[id]=rec;
 if(o.pick){const pk=L.marker([o.pick.lat,o.pick.lng],{draggable:true,zIndexOffset:1000,title:"Drag to adjust",icon:L.divIcon({className:"",html:'<span class="lpk"></span>',iconSize:[26,26],iconAnchor:[13,27]})}).addTo(m),
   ac=L.circle([o.pick.lat,o.pick.lng],{radius:PICK.acc||0,color:"#1769e0",weight:1,fillOpacity:.12,interactive:false}).addTo(m);
  pk.on("dragend",()=>{const p=pk.getLatLng();endPick();setPick({lat:p.lat,lng:p.lng})});m.on("click",e=>{endPick();setPick({lat:e.latlng.lat,lng:e.latlng.lng})});rec.pk=pk;rec.ac=ac}
 setTimeout(()=>{if(LMAP[id]&&LMAP[id].map===m)try{m.invalidateSize()}catch(e){}},200)}
function bindPin(){endPick();["pm","gm","im","mm"].forEach(id=>{if(!$("#"+id))return;if($("#"+id).classList.contains("lmap"))lInit(id,LMO[id]);else mapInit(id,id==="pm"?setPick:undefined)});
 if($("#pm")){pxyUpd();["stt","lm"].forEach(k=>{const e=$("#"+k);if(e)e.addEventListener("input",()=>{delete e.dataset.auto})})}
 if(SHOWME)meDraw();liveDraw()}
let RGT=null;
window.pxyUpd=()=>{const el=$("#pxy");if(!el)return;const n=near(PICK.lat,PICK.lng),w=wardOf(PICK.lat,PICK.lng),out=PICK.lat<B.la0||PICK.lat>B.la1||PICK.lng<B.lo0||PICK.lng>B.lo1;
 el.innerHTML="<b>"+PICK.lat.toFixed(6)+"°N, "+PICK.lng.toFixed(6)+"°E</b>"+(PICK.acc?" · GPS accuracy ±"+Math.round(PICK.acc)+" m":"")+(PICK.addr?"<br>"+esc(PICK.addr):"")+"<br>"+(out?"Outside the Coimbatore area. Using the nearest ward ("+w+").":Math.round(n.d)+" m from "+n.n+" · Ward "+w+" ("+WARDS[w].n+")");if($("#wd"))$("#wd").value=w};
function revGeo(){clearTimeout(RGT);if(navigator.onLine===false)return;const lat=PICK.lat,lng=PICK.lng;RGT=setTimeout(async()=>{try{const r=await fetch("https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=18&addressdetails=1&accept-language=en&lat="+lat+"&lon="+lng);if(!r.ok)return;const j=await r.json();if(lat!==PICK.lat||lng!==PICK.lng)return;PICK.addr=j.display_name||"";
  const a=j.address||{},road=a.road||a.pedestrian||a.footway||a.path||a.neighbourhood||a.suburb||"",st=$("#stt"),lm=$("#lm");
  if(st&&road&&(!st.value||st.dataset.auto)){st.value=[road,a.suburb&&a.suburb!==road?a.suburb:""].filter(Boolean).join(", ");st.dataset.auto=1}
  const lk=j.name||a.amenity||a.shop||a.building||"";if(lm&&lk&&(!lm.value||lm.dataset.auto)){lm.value=lk;lm.dataset.auto=1}
  pxyUpd()}catch(e){}},700)}
window.setPick=(c,acc,fromGps)=>{PICK.lat=c.lat;PICK.lng=c.lng;PICK.acc=acc||null;PICK.addr="";
 const r=LMAP.pm;if(r&&r.pk&&$("#pm")&&$("#pm").classList.contains("lmap")){r.pk.setLatLng([c.lat,c.lng]);r.ac.setLatLng([c.lat,c.lng]);r.ac.setRadius(acc||0);
  if(fromGps)r.map.setView([c.lat,c.lng],acc&&acc>200?15:acc&&acc>60?17:19,{animate:false});else r.map.panTo([c.lat,c.lng],{animate:false})}
 else if($("#pk"))$("#pk").setAttribute("transform",`translate(${px(c.lng)},${py(c.lat)})`);
 if($("#wd"))$("#wd").value=wardOf(c.lat,c.lng);pxyUpd();revGeo()};

/* live crew tracking on the maps */
const fresh=p=>p&&now()-p.t<120000;
const ago=t=>{const s=Math.max(0,Math.round((now()-t)/1000));return s<5?"just now":s<90?s+" s ago":Math.round(s/60)+" min ago"};
function activeCrews(i){return[...new Set(i.wos.map(W).filter(w=>w&&ACTIVE.includes(w.status)).map(w=>w.crew))]}
function liveDraw(){Object.keys(LMAP).forEach(id=>{const r=LMAP[id];if(!r.lv||(id!=="im"&&id!=="mm"))return;r.lv.clearLayers();const i=id==="im"?I(cur):null;if(id==="im"&&!i)return;
  if(i)i.wos.map(W).forEach(w=>{if(!w||!w.trail||!w.trail.length)return;const pts=w.trail.map(p=>[p[0],p[1]]),p=LIVE[w.crew];if(p&&ACTIVE.includes(w.status))pts.push([p.lat,p.lng]);if(pts.length>1)L.polyline(pts,{color:"#0f9d8a",weight:4,opacity:.75,interactive:false}).addTo(r.lv)});
  const crews=i?activeCrews(i).filter(k=>LIVE[k]):Object.keys(LIVE),fit=[];
  crews.forEach(k=>{const p=LIVE[k],ok=fresh(p);if(p.acc)L.circle([p.lat,p.lng],{radius:p.acc,color:"#0f9d8a",weight:1,fillOpacity:.08,interactive:false}).addTo(r.lv);
   if(i)L.polyline([[p.lat,p.lng],[i.lat,i.lng]],{color:"#0f9d8a",weight:2,dashArray:"6 8",opacity:.8,interactive:false}).addTo(r.lv);
   L.marker([p.lat,p.lng],{zIndexOffset:800,icon:L.divIcon({className:"",html:`<span class="lcrew${ok?"":" stale"}">🚚</span>`,iconSize:[30,30],iconAnchor:[15,15]})}).addTo(r.lv).bindTooltip((USERS[k]?USERS[k].n:"Crew")+" · "+ago(p.t)+(p.acc?" · ±"+Math.round(p.acc)+" m":""),{direction:"top",offset:[0,-14]});fit.push([p.lat,p.lng])});
  if(i&&fit.length&&!r.fitted){r.fitted=true;r.map.fitBounds([...fit,[i.lat,i.lng]],{padding:[40,40],maxZoom:17,animate:false})}});
 liveText()}
function liveText(){const el=$("#livetxt");if(!el)return;const i=I(cur);if(!i)return;const crews=activeCrews(i);
 el.innerHTML=crews.map(k=>{const p=LIVE[k],n=uname(k);if(!p)return`<p class="my-1"><span class="pulse off"></span><b>${n}</b>: waiting for the crew's phone to share its location.</p>`;
  const d=hav(p,i),sp=p.spd>1?p.spd:5.5,eta=Math.max(1,Math.round(d/sp/60)),ok=fresh(p);
  return`<p class="my-1"><span class="pulse${ok?"":" off"}"></span><b>${n}</b> · ${d<40?"at the reported spot":km(d)+" from the reported spot · about "+eta+" min away"}${p.acc?" · GPS ±"+Math.round(p.acc)+" m":""} · ${ok?"updated "+ago(p.t):"last seen "+ago(p.t)}</p>`}).join("")}
setInterval(()=>{if($("#livetxt"))liveDraw()},5000);
function liveCard(i){if(!activeCrews(i).length)return"";return`<div class="card livebox"><h2>Live crew tracking</h2><div id="livetxt" aria-live="polite"></div><small>The crew's phone shares its GPS position while the work order is accepted or in progress. The green line on the map is the route travelled.</small></div>`}

