function issueTable(list){const all=list.length;list=list.filter(i=>(!FL.s||i.status===FL.s)&&(!FL.q||(i.id+i.cat+i.street).toLowerCase().includes(FL.q.toLowerCase())));const bar=`<div class="row" style="margin-bottom:10px"><input style="max-width:260px" placeholder="Search issue, category or street" value="${esc(FL.q)}" onchange="FL.q=this.value;render()" aria-label="Search issues"><select style="width:auto" onchange="FL.s=this.value;render()" aria-label="Filter by status"><option value="">All statuses</option>${["Under Verification","Needs Info","Assigned","In Progress","Resolved","Closed","Escalated","Reopened","Rejected","Merged"].map(s=>`<option ${FL.s===s?"selected":""}>${s}</option>`).join("")}</select></div>`;if(!list.length)return bar+`<div class="card">${all?"No issues match your filters.":"Nothing here yet."} New issues in your area will appear in this list.</div>`;
 return bar+`<div class="card tw"><table><thead><tr><th>Issue</th><th>Location</th><th>Department</th><th>Priority</th><th>Status</th></tr></thead><tbody>${list.slice().sort((a,b)=>pr(b)-pr(a)).map(i=>{const b=band(i);return`<tr class="click" tabindex="0" onclick="openI('${i.id}')" onkeydown="if(event.key==='Enter')openI('${i.id}')"><td><b>${i.id}</b> ${i.sos?'<span class="tag bad">SOS</span>':""}<br>${esc(i.cat)}</td><td>${esc(i.street)}<br><small>Ward ${i.ward} · ${i.support} supporter${i.support>1?"s":""}</small></td><td>${DEPTS[i.dept].n}<br><small>${ag(i)}</small></td><td><span class="tag ${b[1]}">${b[0]}</span> ${pr(i)}/100</td><td>${st(i.status)}${slaTag(i)}${i.verified&&i.status==="Under Verification"?'<br><small>Verified · awaiting work order</small>':""}${i.dup&&USERS[me].role!=="citizen"&&CA.isOpen(i)?`<br><span class="tag warn">Possible duplicate of ${i.dup.id} · S ${i.dup.s.toFixed(2)}</span>`:""}${i.autoClosed?'<br><small>Closed without confirmation</small>':""}${i.mergedInto?"<br><small>into "+i.mergedInto+"</small>":""}</td></tr>`}).join("")}</tbody></table></div>`}
