  if(w.status==="In Progress")a+=`<div class="two"><div><label for="r${w.id}">Resolution note (required)</label><textarea id="r${w.id}" rows="2"></textarea><label for="f${w.id}">After-repair photo (required)</label><input type="file" id="f${w.id}" accept="image/*" capture="environment"><div class="row" style="margin-top:10px"><button class="b k" onclick="subWO('${w.id}')">Submit for verification</button></div></div><div><label for="b${w.id}">Report a blocker</label><input id="b${w.id}" placeholder="e.g. valve access blocked by parked vehicles"><div style="margin-top:10px"><button class="b g" onclick="blkWO('${w.id}')">Report blocker</button></div></div></div>`;
