const PRESETS=[["Pothole / damaged road","Deep pothole on the road, two-wheelers are skidding and swerving into traffic.","சாலையில் ஆழமான குழி உள்ளது, இருசக்கர வாகனங்கள் சறுக்கி விழுகின்றன."],["Garbage accumulation","Garbage has not been cleared for several days and there is a bad smell.","பல நாட்களாக குப்பை அகற்றப்படவில்லை, துர்நாற்றம் வீசுகிறது."],["Broken streetlight","Streetlight is not working and the road is dark at night.","தெருவிளக்கு எரியவில்லை, இரவில் சாலை இருட்டாக உள்ளது."],["Water leakage","Water pipe is leaking and water is flowing onto the road.","குடிநீர் குழாய் கசிந்து சாலையில் தண்ணீர் ஓடுகிறது."],["Blocked drain","Drain is blocked and sewage is overflowing onto the street.","வடிகால் அடைத்து கழிவுநீர் தெருவில் வழிகிறது."]];
window.usePreset=n=>{const p=PRESETS[n],c=$("#cat"),d=$("#ds");c.value=p[0];c.dataset.m=1;d.value=lang==="ta"?p[2]:p[1];$("#cc").textContent=d.value.length+"/500";d.focus()};
let draft=null;
function vNew(sos){return`<h1>${sos?"Emergency SOS report":"New complaint"}</h1><p class="sub">${sos?"SOS reports are fast-tracked with a 4-hour repair target and the top priority score.":"Tell us what is wrong and where. We check for similar nearby reports first."}</p><div class="card ${sos?"sos":""}"><form id="f" onsubmit="return subNew(event,${!!sos})" novalidate>
 <label for="cat">Category</label><select id="cat" onchange="this.dataset.m=1">${Object.keys(CATS).map(c=>`<option>${c}</option>`).join("")}</select>
 <label>Quick draft presets</label><div class="chips">${PRESETS.map((p,n)=>`<button type="button" class="chipb" onclick="usePreset(${n})">${esc(p[0].split(" /")[0])}</button>`).join("")}</div><small>Tap a preset to fill the description in the current language, then edit it. Voice input is not part of this version.</small><label for="ds">Description (Tamil or English)</label><textarea id="ds" rows="3" maxlength="500" oninput="$('#cc').textContent=this.value.length+'/500';autoCat()"></textarea><small id="cc">0/500</small><div class="err" id="e-ds"></div>
 <div class="two"><div><label for="wd">Ward</label><select id="wd">${Object.keys(WARDS).map(k=>`<option value="${k}">${k} · ${WARDS[k].n}</option>`).join("")}</select></div><div><label for="stt">Street</label><input id="stt" placeholder="e.g. Avinashi Road near Hopes College"><div class="err" id="e-stt"></div></div></div>
 <label for="lm">Nearest landmark, door number or pole ID (required)</label><input id="lm"><div class="err" id="e-lm"></div>
 <label for="ph">Photos of the problem (1 to 3)</label><input type="file" id="ph" accept="image/*" multiple><div class="err" id="e-ph"></div>
 <label>Pin the exact spot: use GPS, click the map, or drag the red pin</label>${mapSVG("pm",{pick:PICK,pins:S.issues,h:340})}<div class="row" style="margin-top:6px"><button type="button" class="b g" onclick="gps()">📍 Use my exact location</button><span id="pxy" aria-live="polite"></span></div>
 <div class="row" style="margin-top:14px"><button class="b ${sos?"r":""}" type="submit" id="sb">${sos?"Send SOS":"Check and submit"}</button></div></form><div id="dup"></div></div>`}
window.autoCat=()=>{const c=$("#cat");if(!c||c.dataset.m)return;const s=$("#ds").value.toLowerCase(),m=[[/pothole|crater|pit\b/,"Pothole / damaged road"],[/footpath|pavement|sidewalk/,"Broken footpath"],[/tree|branch/,"Fallen tree / branch"],[/garbage|waste|trash|dump|smell/,"Garbage accumulation"],[/street ?light|lamp|dark|pole/,"Broken streetlight"],[/leak|pipe|water supply|burst/,"Water leakage"],[/drain|sewage|overflow|clog|manhole/,"Blocked drain"],[/dog|cattle|cow|monkey/,"Stray animal menace"],[/toilet|urinal/,"Public toilet maintenance"]].find(x=>x[0].test(s));if(m)c.value=m[1]};
const dBody=()=>({cat:draft.cat,desc:draft.desc,ward:draft.ward,street:draft.street,landmark:draft.landmark,lat:draft.lat,lng:draft.lng,acc:draft.acc||undefined,addr:draft.addr||"",sos:!!draft.sos,hashes:(draft.hashes||[]).filter(Boolean)});
window.subNew=(e,sos)=>{e.preventDefault();const v=id=>$("#"+id).value.trim(),er={};
 if(v("ds").length<10)er.ds="Describe the problem in at least 10 characters.";if(v("stt").length<2)er.stt="Enter the street name.";if(!v("lm"))er.lm="A landmark, door number or pole ID is required.";if(!$("#ph").files.length)er.ph="Attach at least one photo of the problem.";else if($("#ph").files.length>3)er.ph="Attach at most three photos.";
 ["ds","stt","lm","ph"].forEach(k=>$("#e-"+k).textContent=er[k]||"");if(Object.keys(er).length)return false;
 draft={cat:v("cat"),desc:v("ds"),ward:v("wd"),street:v("stt"),landmark:v("lm"),lat:PICK.lat,lng:PICK.lng,acc:PICK.acc,addr:PICK.addr,sos};
 const box=$("#dup"),files=[...$("#ph").files];box.innerHTML='<div class="card ai">CivicFix AI (simulated) is analysing your report…</div>';
 (async()=>{draft.photos=[];draft.hashes=[];for(const f of files){const p=await thumb(f,OFFLINE?800:1280,OFFLINE?.6:.8);if(!p){box.innerHTML="";$("#e-ph").textContent="A photo could not be read. Choose JPG or PNG images.";return}draft.photos.push(p);draft.hashes.push(await ahash(p))}
  try{const r=await P("/api/issues/check",dBody());draft.ai=r.ai;draft.dups=r.duplicates}
  catch(err){if(!err.offline){box.innerHTML="";return toast(err.message)}
   // server unreachable: run the same duplicate rules in the browser on the saved copy
   draft.ai=null;draft.dups=CA.findDuplicates({...dBody(),ph:draft.hashes},S.issues.filter(i=>!i.local&&!i.by.includes(me))).map(m=>{const i=I(m.id);return{...m,status:i.status,street:i.street,cat:i.cat,dist:m.d,support:i.support}})}
  showDup()})();return false};
window.aiBox=()=>draft.ai?`<div class="card ai"><b>CivicFix AI diagnosis · simulated rule engine</b><br>Defect: ${esc(draft.ai.defect)} · severity ${Math.round(draft.ai.severity*100)}% · confidence ${draft.ai.confidence}%${draft.ai.suggested?`<br>The description also looks like: <b>${esc(draft.ai.suggested)}</b>. Change the category above if that fits better.`:""}<br><small>${esc(draft.ai.reason)}</small></div>`:OFFLINE?`<div class="card ai">The server is unreachable. Nearby issues were checked in this browser against the saved copy.</div>`:"";
window.showDup=()=>{const dups=draft.dups||[];if(!dups.length)return finishNew(false);
 const auto=dups.find(i=>i.band==="auto"&&!draft.sos);
 $("#dup").innerHTML=aiBox()+`<hr><h2>Similar issues nearby</h2><small>Open ${esc(draft.cat)} issues within ${CA.radiusOf(draft.cat)} m. Match score S = 0.5 × location + 0.3 × text + 0.2 × photo. Supporting an existing issue raises its priority and avoids a duplicate.</small>${dups.map(i=>`<div class="card" style="margin-top:10px"><b>${i.id}</b> ${st(i.status)} · ${km(i.dist)} away · ${i.support} supporter${i.support>1?"s":""} <span class="tag ${i.band==="auto"?"bad":i.band==="review"?"warn":""}">S ${i.s.toFixed(2)}</span><br>${esc(i.street)} · ${esc(i.cat)}<br><small>location ${i.geo.toFixed(2)} · text ${i.text.toFixed(2)} · photo ${i.image.toFixed(2)}${i.band==="auto"?" · same problem: a new report is linked to this issue automatically":i.band==="review"?" · likely the same: the ward officer will decide":""}</small><div class="row" style="margin-top:8px"><button class="b" onclick="run(()=>api.support('${i.id}'),()=>{toast('You now support ${i.id}');cur='${i.id}';view='issue'})">Support this issue</button></div></div>`).join("")}<div class="row" style="margin-top:6px">${auto?`<button class="b" onclick="finishNew(false)">Add my report to ${auto.id}</button>`:`<button class="b" onclick="finishNew(false)">Submit my report</button>`}<button class="b g" onclick="finishNew(true)">This is a different problem</button></div>`;$("#dup").scrollIntoView({behavior:"smooth",block:"nearest"});applyTa()};
const newPick=()=>({lat:11.0050,lng:76.9700});
window.finishNew=async distinct=>{if(!draft||draft.busy)return;draft.busy=1;const body={...dBody(),photos:draft.photos,distinct:distinct===true};
 try{const r=await P("/api/issues",body);await refresh();toast(r.linked?(r.own?"You had already reported this. Your new report was added to "+r.id+".":"Same problem as "+r.id+" (match "+r.match.s.toFixed(2)+"). Your report was linked to it and counts as support."):"Reference ID "+r.id+" · routed to "+DEPTS[r.dept].n+" ("+AGENCIES[r.agency].s+")");PICK=newPick();draft=null;cur=r.id;view="issue";render()}
 catch(e){if(!e.offline){draft.busy=0;return toast(e.message)}
  const id="LOCAL-"+Date.now().toString(36).toUpperCase(),l=outbox();l.push({id,u:me,t:now(),body});if(!setOutbox(l)){draft.busy=0;return toast("The storage of this browser is full. Try again with fewer photos.")}
  addQueued();offBar();toast("Saved in this browser as "+id+". It is sent when the server is back.");PICK=newPick();draft=null;cur=id;view="issue";render()}};
function vNotes(){const l=S.notes;if(l.some(n=>!n.read)){P("/api/notifications/read").catch(()=>{});setTimeout(()=>{l.forEach(n=>n.read=true);renderNav()},0)}if(!l.length)return`<h1>Notifications</h1><div class="card">No notifications yet. Updates on your issues will appear here. SMS and WhatsApp delivery is simulated.</div>`;return`<h1>Notifications</h1><p class="sub">In-app notifications arrive live. SMS and WhatsApp delivery is simulated.</p><div class="card">${l.map(n=>`<p style="margin:0 0 10px">${n.read?"":'<span class="tag bad">New</span> '}<b>${esc(n.m)}</b><br><small>${fmt(n.t)}</small></p>`).join("")}</div>`}
function vKarma(){const k=S.karma||0,tr=CA.tier(k);return`<h1>Civic Karma</h1><p class="sub">You earn ${S.karmaPts} points once for each repair you confirm.</p><div class="grid"><div class="stat"><b>${k}</b><span>Points</span></div><div class="stat"><b>${tr.name}</b><span>Current tier</span></div><div class="stat"><b>${tr.next?tr.next.at-k:"–"}</b><span>${tr.next?"Points to "+tr.next.name:"Highest tier reached"}</span></div></div><div class="card tw"><h2>Tiers</h2><table><thead><tr><th>Tier</th><th>From</th></tr></thead><tbody>${CA.TIERS.map(x=>`<tr><td>${x[1]===tr.name?"<b>"+x[1]+"</b>":x[1]}</td><td>${x[0]} points</td></tr>`).join("")}</tbody></table></div>`}
function vAdmin(){const l=S.issues,an=S.analytics||{recurrence:[],byAgency:{}},wr=Object.keys(WARDS).map(k=>{const x=l.filter(i=>i.ward===k),c=x.filter(i=>["Closed","Resolved"].includes(i.status)).length;return`<tr><td>Ward ${k} · ${WARDS[k].n}</td><td>${x.length}</td><td>${x.length-c}</td><td>${x.length?Math.round(c/x.length*100):0}%</td><td>${x.length?Math.round(x.reduce((a,i)=>a+pr(i),0)/x.length):0}</td></tr>`}).join("");
return`<h1>City dashboard</h1><p class="sub">Coimbatore · all figures come from the live records on this server.</p>${stats(l)}<div class="two"><div class="card"><h2>Issues by status</h2><canvas id="c1" height="200"></canvas></div><div class="card"><h2>Issues by department</h2><canvas id="c2" height="200"></canvas></div></div><div class="card tw"><h2>Ward performance</h2><table><thead><tr><th>Ward</th><th>Issues</th><th>Open</th><th>Resolved</th><th>Avg priority</th></tr></thead><tbody>${wr}</tbody></table></div>
<div class="two"><div class="card tw"><h2>Recurrence analytics</h2><small>Places where the same kind of problem keeps coming back (same category within 250 m).</small><table class="mt-2"><thead><tr><th>Location</th><th>Category</th><th>Reports</th><th>Open</th></tr></thead><tbody>${an.recurrence.map(c=>`<tr class="click" tabindex="0" onclick="openI('${c.ids[c.ids.length-1]}')"><td>${esc(c.street)}<br><small>Ward ${c.ward} · last ${fmt(c.last)}</small></td><td>${esc(c.cat)}</td><td>${c.count>1?c.count:"Flagged recurring"}</td><td>${c.open}</td></tr>`).join("")||'<tr><td colspan="4">No recurring problems detected yet.</td></tr>'}</tbody></table></div>
<div class="card tw"><h2>Agency routing</h2><small>Which agency each issue was routed to.</small><table class="mt-2"><thead><tr><th>Agency</th><th>Issues</th><th>Open</th></tr></thead><tbody>${Object.keys(AGENCIES).map(k=>{const a=an.byAgency[k]||{total:0,open:0};return`<tr><td><b>${esc(AGENCIES[k].s)}</b><br><small>${esc(AGENCIES[k].n)}</small></td><td>${a.total}</td><td>${a.open}</td></tr>`}).join("")}</tbody></table></div></div>
${askCard()}<div class="two"><div class="card"><h2>SLA compliance</h2>${(()=>{const c=an.sla||{},o=S.wos.filter(openWO).length;return`Open work orders: ${o}<br><span class="tag ok">On Track ${c["On Track"]||0}</span> <span class="tag warn">At Risk ${c["At Risk"]||0}</span> <span class="tag bad">Breached ${c.Breached||0}</span><br><small>At Risk starts when 75% of the SLA time is used. A breach escalates the issue. Emergency SOS has a 4-hour SLA.</small>`})()}</div><div class="card"><h2>Duplicates and closure</h2>${(()=>{const d=an.dup||{};return`${d.linked||0} report(s) linked to an existing issue · ${d.merged||0} issue(s) merged · ${d.pending||0} suggestion(s) waiting for an officer<br>${d.autoClosed||0} issue(s) closed without citizen confirmation (7-day rule)`})()}</div></div>`}
function vAudit(){return`<h1>${t("Audit history")}</h1><button class="b g" onclick="exportCSV()" style="margin-bottom:10px">Export CSV</button><div class="card tw"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Ref</th><th>Note</th></tr></thead><tbody>${S.audit.map(a=>`<tr><td>${fmt(a.t)}</td><td>${uname(a.a)}</td><td>${esc(a.act)}</td><td>${esc(a.ref)}</td><td>${esc(a.note)}</td></tr>`).join("")||'<tr><td colspan="5">No actions recorded yet.</td></tr>'}</tbody></table></div>`}
const WN={sev:"Severity",safety:"Public safety",sens:"Sensitive location (near schools and hospitals)",support:"Citizen support (number of reports)",recur:"Recurrence"};
function vCfg(){const w=S.weights;return`<h1>Priority settings</h1><p class="sub">Change the weights and the scores of every issue update immediately.</p><div class="card"><h2>Priority weights</h2>${Object.keys(w).map(k=>`<label for="w${k}">${WN[k]||k} weight: <b id="v${k}">${w[k]}</b></label><input type="range" id="w${k}" min="0" max="50" value="${w[k]}" oninput="$('#v${k}').textContent=this.value">`).join("")}<div style="margin-top:12px"><button class="b" onclick="saveW()">Save weights</button></div></div><div class="card"><h2>Department settings</h2><small>Default SLA target in hours for new work orders of each department. Emergency SOS is always 4 hours.</small><div class="two">${Object.keys(DEPTS).map(k=>`<div><label for="ds${k}">${esc(DEPTS[k].n)}</label><input id="ds${k}" type="number" min="1" max="720" value="${DEPTS[k].sla}"></div>`).join("")}</div><div style="margin-top:12px"><button class="b" onclick="saveD()">Save department settings</button></div></div>`}
window.saveW=()=>{const w={};Object.keys(S.weights).forEach(k=>w[k]=+$("#w"+k).value);run(()=>http("PUT","/api/config/weights",w),()=>toast("Weights saved"))};
window.saveD=()=>{const d={};Object.keys(DEPTS).forEach(k=>d[k]=+$("#ds"+k).value);run(()=>http("PUT","/api/config/departments",d),()=>toast("Department settings saved"))};
function vDemo(){return`<h1>Demo data</h1><p class="sub">Everything is saved on the server in data/db.json. Reset to restore the original Coimbatore sample records. User accounts are kept.</p><div class="card">${S.issues.length} issues, ${S.wos.length} work orders, ${S.audit.length} audit events stored.<div style="margin-top:10px"><button class="b r" onclick="resetDemo()">Reset all demo data</button></div></div>`}
window.resetDemo=()=>{if(confirm("Delete all complaints and work orders and restore the sample data?"))run(()=>P("/api/admin/reset",{confirm:"RESET"}),()=>toast("Sample data restored"))};
function aiCard(i){const a=i.ai,u=USERS[me];return`<div class="card ai"><div class="row" style="justify-content:space-between"><h2 style="margin:0">CivicFix AI briefing</h2><button class="b" onclick="run(()=>P('/api/issues/${i.id}/briefing'))">${a?"Refresh":"Generate"} briefing</button></div>${a?`<p>${esc(a.summary)}</p><p lang="ta">${esc(a.tamil)}</p><p><b>Risk:</b> ${esc(a.risk)}<br><b>Suggested repair:</b> ${esc(a.repair)}<br><b>Citizen update:</b> ${esc(a.update)}</p>${u.role==="officer"?`<button class="b g" onclick="useAI('${i.id}')">Use as repair instructions</button> `:""}<small>${esc(a.src)}</small>`:`<small>Simulated AI: a built-in rule engine drafts a summary, risk note, repair plan and Tamil version. No live AI model is called.</small>`}</div>`}
window.useAI=id=>{const t=$("#in");if(t){t.value=I(id).ai.repair;if(t.closest("details"))t.closest("details").open=true;toast("Repair plan added to the form")}else toast("Verify the issue first, then the work-order form appears")};
window.localAsk=(q,def)=>{const s=q.toLowerCase(),open=S.issues.filter(i=>CA.isOpen(i)),
 top=l=>l.slice().sort((a,b)=>pr(b)-pr(a)).slice(0,3).map(i=>i.id+" ("+i.cat+", "+i.street+", priority "+pr(i)+")").join("; "),wm=s.match(/ward\s*(\d+)/);
 if(wm)return WARDS[wm[1]]?(()=>{const l=open.filter(i=>i.ward===wm[1]);return "Ward "+wm[1]+" ("+WARDS[wm[1]].n+") has "+l.length+" open issue(s)."+(l.length?" Highest priority: "+top(l)+".":"")})():"This city model covers wards "+Object.keys(WARDS).join(", ")+" only.";
 if(/overdue|late|breach|deadline|sla/.test(s)){const l=S.wos.filter(w=>w.due<now()&&!["Verified","Completed","Cancelled"].includes(w.status));return l.length?l.length+" work order(s) are past deadline: "+l.map(w=>w.id+" ("+DEPTS[w.dept].n+", issue "+w.issue+")").join("; ")+".":"No work orders are past their deadline."}
 if(/sos|emergency/.test(s)){const l=open.filter(i=>i.sos);return l.length?l.length+" open SOS report(s): "+l.map(i=>i.id+" at "+i.street).join("; ")+".":"There are no open SOS reports."}
 if(/agency|highway|tangedco|cmwssb|gcc|corporation/.test(s))return Object.keys(AGENCIES).map(k=>AGENCIES[k].s+": "+open.filter(i=>i.agency===k).length+" open").join("; ")+".";
 if(/department|workload|crew|busy/.test(s))return Object.keys(DEPTS).map(k=>DEPTS[k].n+": "+open.filter(i=>i.dept===k).length+" open").join("; ")+".";
 if(/recur|repeat|again|hotspot/.test(s)){const l=(S.analytics||{recurrence:[]}).recurrence;return l.length?"Recurring trouble spots: "+l.slice(0,4).map(c=>c.cat+" at "+c.street+" ("+(c.count>1?c.count+" reports":"flagged")+")").join("; ")+".":"No recurring problems detected yet."}
 if(/how many|count|total|status|summary|overview/.test(s)){const c={};S.issues.forEach(i=>c[i.status]=(c[i.status]||0)+1);return S.issues.length+" issues in total: "+Object.keys(c).map(k=>c[k]+" "+k).join(", ")+"."}
 return def()};
function askCard(){return`<div class="card ai"><h2>Ask the city</h2><small>Simulated AI: a rule engine answers from live data. Try: overdue work, ward 63, SOS, department workload, agency, recurring.</small><div class="row" style="margin-top:8px"><label for="q" style="position:absolute;left:-999px">Question</label><input id="q" style="flex:1;min-width:200px" value="Which three issues should the commissioner look at first, and why?" onkeydown="if(event.key==='Enter')askCity()"><button class="b" onclick="askCity()">Ask</button></div><p id="qa" aria-live="polite"></p></div>`}
window.askCity=()=>{const open=S.issues.filter(i=>CA.isOpen(i)).sort((a,b)=>pr(b)-pr(a));const local=()=>"Look first at: "+open.slice(0,3).map(i=>{const late=i.wos.map(W).filter(w=>w&&w.due<now()&&!["Verified","Completed","Cancelled"].includes(w.status)).length;return i.id+" ("+i.cat+", "+i.street+", priority "+pr(i)+(late?", "+late+" work order(s) past deadline":"")+")"}).join("; ")+".";$("#qa").textContent="CivicFix rule engine: "+localAsk($("#q").value,local)};
function vGate(){const l=S.issues,done=l.filter(i=>["Closed","Resolved"].includes(i.status)).length,br=S.wos.filter(w=>w.due<now()&&!["Verified","Completed","Cancelled"].includes(w.status)).length;
 const wt=Object.keys(WARDS).map(k=>{const x=l.filter(i=>i.ward===k);return`<tr><td>Ward ${k} · ${WARDS[k].n}</td><td>${x.length}</td><td>${x.filter(i=>CA.isOpen(i)&&i.status!=="Resolved").length}</td></tr>`}).join("");
 return`<section class="hero"><div><h1 class="big" style="border:0;padding:0">${t("Report it once. Track it to the fix.")}</h1><p>Potholes, garbage, broken streetlights and leaks across Coimbatore. Reports about the same problem join one issue, every department is held to a deadline, and a repair only closes when you confirm it.</p><div class="row"><button class="b" onclick="portal='citizen';go=null;view='login';render()">${t("Citizen portal")}</button><button class="b g" onclick="portal='authority';go=null;view='login';render()">${t("Authority portal")}</button><button class="b r" onclick="portal='citizen';go='sos';view='login';render()">${t("Emergency SOS")}</button></div></div>
 <div class="hr">${mapSVG("gm",{pins:S.issues,h:430})}<div class="leg"><span>Live from the server, real coordinates</span><span class="lg c">● Critical</span><span class="lg h">● High</span><span class="lg m">● Medium</span><span class="lg l">● Low</span></div></div></section>
 <div class="grid" style="margin-bottom:14px"><div class="stat"><b>${l.length}</b><span>Issues reported</span></div><div class="stat"><b>${done}</b><span>Repaired</span></div><div class="stat"><b>${l.reduce((a,i)=>a+i.support,0)}</b><span>Citizen supports</span></div><div class="stat"><b>${br}</b><span>Work orders past deadline</span></div></div>
 <div class="card ai"><h2>Where the AI works</h2><ul><li><b>Report analysis:</b> reads the description, then scores severity, public-safety risk and location sensitivity, and routes the report to the right department and agency.</li><li><b>Duplicate matching:</b> scores every new report against open ones nearby (S = 0.5 × location + 0.3 × text + 0.2 × photo). 0.80 or more joins the existing issue, 0.55 to 0.79 goes to the ward officer, lower is a new issue.</li><li><b>Officer briefing:</b> summary, risk, repair plan and a Tamil version for every issue.</li><li><b>Ask the city:</b> administrators question live data in plain language.</li></ul><small>CivicFix AI in this build is simulated: a transparent built-in rule engine does these jobs, and every result is labelled. No live AI model is called.</small></div>
 <div class="two"><div class="card"><h2>Municipal helpline</h2><p style="margin:0">Coimbatore Corporation control room: <b>0422-2302323</b><br>Water supply helpline: <b>0422-6610000</b><br>Emergency services: <b>112</b><br><small>Numbers are from public listings and may change. Calls are not connected from this app.</small></p></div><div class="card"><h2>Civic alerts</h2><p style="margin:0"><span class="tag warn">Monsoon watch</span> Low-lying areas near the Noyyal river, Ukkadam and Valankulam lake bunds are on drainage watch. Report waterlogging or fallen wires as an SOS.<br><small>Sample alert for demonstration.</small></p></div></div>
 <div class="card tw"><h2>Ward snapshot</h2><table><thead><tr><th>Ward</th><th>Issues</th><th>Open</th></tr></thead><tbody>${wt}</tbody></table></div>`}
function vLogin(){const ids=DEMO.filter(d=>portal==="citizen"?d.role==="citizen":d.role!=="citizen"),cz=portal==="citizen";
 return`<p><a href="#" onclick="view='gate';render();return false">← Back to home</a></p><div class="login"><div class="card"><h1>${cz?"Citizen sign in":"Authority sign in"}</h1><p class="sub">${cz?"Sign in with your mobile number and password, or pick a demo profile.":"Sign in with your staff login ID and password, or pick a demo profile."}</p><form onsubmit="return doLogin(event)" novalidate><label for="un">${cz?"Mobile number or login ID":"Login ID"}</label><input id="un" autocomplete="username" autocapitalize="none"><label for="pw">Password</label><input id="pw" type="password" autocomplete="current-password"><div class="err" id="lerr" role="alert"></div><button class="b" type="submit" style="margin-top:12px">Sign in</button></form>
 ${cz?`<hr class="my-4"><h2>New here? Create a citizen account</h2><form onsubmit="return doReg(event)" novalidate><label for="rn">Your name</label><input id="rn" autocomplete="name" maxlength="40"><label for="rm">Mobile number (10 digits)</label><input id="rm" inputmode="numeric" maxlength="10" autocomplete="tel-national"><label for="rw">Choose a password (at least 6 characters)</label><input id="rw" type="password" autocomplete="new-password"><div class="err" id="rerr" role="alert"></div><button class="b g" type="submit" style="margin-top:12px">Create account</button></form><small class="block mt-2">No OTP is sent in this build: mobile verification is simulated.</small>`:""}</div>
 <div class="card"><h2>Demo profiles</h2>${ids.map(d=>`<button class="prof" onclick="fillP('${d.id}')"><b>${esc(d.n)}</b><small>${ROLE[d.role]} · login ID: ${d.id}</small></button>`).join("")}<small>Demo profiles use the password demo123. Each role opens a different workspace and sees only what its permissions allow.</small></div></div>`}
async function enter(){connectES();view=go||"home";go=null;GEO.denied=false;render()}
window.doLogin=e=>{e.preventDefault();(async()=>{try{await P("/api/auth/login",{login:$("#un").value.trim(),password:$("#pw").value});await refresh();enter()}catch(err){$("#lerr").textContent=err.message}})();return false};
window.doReg=e=>{e.preventDefault();(async()=>{try{await P("/api/auth/register",{name:$("#rn").value.trim(),phone:$("#rm").value.trim(),password:$("#rw").value});await refresh();enter();toast("Welcome! Your account is ready.")}catch(err){$("#rerr").textContent=err.message}})();return false};
window.fillP=k=>{$("#un").value=k;$("#pw").value="demo123";$("#pw").focus()};

/* ---------------- render ---------------- */
function renderNav(){if(!me){$("#nav").innerHTML="";return}const u=USERS[me],navs=NAVS[u.role],un=unread();
 $("#nav").innerHTML=navs.map(([k,l])=>`<button class="${view===k||(view==="issue"&&k==="home")?"on":""}" onclick="view='${k}';render()">${t(l)}${k==="notes"&&un?`<span class="tag bad">${un}</span>`:""}</button>`).join("");if(lang==="ta")applyTa()}
function render(){render0();applyTa()}
function render0(){killMaps();$("#upd").hidden=true;$("#chip").hidden=$("#out").hidden=!me;if(me)$("#chip").textContent=USERS[me].n.split(" (")[0]+" · "+ROLE[USERS[me].role];document.querySelector(".layout").classList.toggle("nologin",!me);shareSync();
 charts.forEach(c=>c.destroy());charts=[];
 if(!me){$("#nav").innerHTML="";$("#main").dataset.role="";$("#main").innerHTML=view==="login"?vLogin():vGate();bindPin();return}
 const u=USERS[me];renderNav();
 const V={map:vMap,home:vHome,new:()=>vNew(0),sos:()=>vNew(1),notes:vNotes,karma:vKarma,issue:vIssue,wo:()=>vWO(false),audit:vAudit,cfg:vCfg,demo:vDemo};
 if(!NAVS[u.role].some(n=>n[0]===view)&&view!=="issue")view="home";
 $("#main").dataset.role=u.role;$("#main").innerHTML=(V[view]||vHome)();bindPin();
 if(u.role==="admin"&&view==="home"&&window.Chart){const cnt=(f,keys)=>keys.map(k=>S.issues.filter(i=>f(i)===k).length),ss=["Under Verification","Needs Info","Assigned","In Progress","Resolved","Closed","Escalated","Reopened","Rejected","Merged"],dk=Object.keys(DEPTS);
  charts.push(new Chart($("#c1"),{type:"bar",data:{labels:ss,datasets:[{data:cnt(i=>i.status,ss),backgroundColor:"#1769e0"}]},options:{plugins:{legend:{display:false}},scales:{y:{ticks:{precision:0}}}}}));
  charts.push(new Chart($("#c2"),{type:"doughnut",data:{labels:dk.map(k=>DEPTS[k].n),datasets:[{data:cnt(i=>i.dept,dk),backgroundColor:["#07265e","#1769e0","#4a90ff","#0e9fbc"]}]}}))}}
$("#out").onclick=async()=>{SHARE=false;SHOWME=false;geoSync();try{await P("/api/auth/logout")}catch(e){}me=null;try{await refresh()}catch(e){}view="gate";connectES();render()};
$("#lang").onclick=()=>{lang=lang==="ta"?"en":"ta";localStorage.setItem("ucirp-lang",lang);render()};
Object.assign(TA,{"Coimbatore City Municipal Corporation":"கோயம்புத்தூர் மாநகராட்சி","Working model: accounts, complaints and photos are saved on this server. CivicFix AI is a simulated rule engine, and SMS/WhatsApp are simulated as in-app notifications. CCMC control room 0422-2302323.":"செயல்படும் மாதிரி: கணக்குகள், புகார்கள், புகைப்படங்கள் இந்தச் சேவையகத்தில் சேமிக்கப்படுகின்றன. CivicFix AI என்பது உருவகப்படுத்தப்பட்ட விதி அடிப்படையிலான இயந்திரம்; SMS/WhatsApp ஆகியவை செயலியினுள் அறிவிப்புகளாக உருவகப்படுத்தப்படுகின்றன. CCMC கட்டுப்பாட்டு அறை 0422-2302323.","Live crew tracking":"பணிக்குழு நேரலை கண்காணிப்பு","Create account":"கணக்கை உருவாக்கு","Your name":"உங்கள் பெயர்","Mobile number (10 digits)":"கைபேசி எண் (10 இலக்கங்கள்)","Send reply":"பதிலை அனுப்பு","Your reply":"உங்கள் பதில்","Responsible agency":"பொறுப்பு நிறுவனம்","Correct department routing":"துறை ஒதுக்கீட்டைத் திருத்து","Recurrence analytics":"மீள்நிகழ்வு பகுப்பாய்வு","Agency routing":"நிறுவன ஒதுக்கீடு","Agency":"நிறுவனம்","Reports":"புகார்கள்","Live location":"நேரலை இருப்பிடம்","🧭 Navigate to the exact spot":"🧭 சரியான இடத்திற்கு வழிகாட்டு","New updates · tap to refresh":"புதிய புதுப்பிப்புகள் · புதுப்பிக்க தட்டவும்","Login ID":"உள்நுழைவு ஐடி","Mobile number or login ID":"கைபேசி எண் அல்லது உள்நுழைவு ஐடி","Getting your exact location…":"உங்கள் சரியான இருப்பிடம் பெறப்படுகிறது…"});
if("serviceWorker" in navigator&&window.isSecureContext)navigator.serviceWorker.register("sw.js").catch(()=>{});
